import random
from collections import Counter, deque

def assert_valid(grid, rows, cols):
    assert len(grid) == rows
    assert all(len(row) == cols for row in grid)
    flat = [value for row in grid for value in row]
    assert set(flat) == {1, 2, 3, 4}
    assert Counter(flat) == {label: rows * cols // 4 for label in range(1, 5)}
    for label in range(1, 5):
        cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == label}
        seen = {next(iter(cells))}
        queue = deque(seen)
        while queue:
            r, c = queue.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                neighbor = (r + dr, c + dc)
                if neighbor in cells and neighbor not in seen:
                    seen.add(neighbor)
                    queue.append(neighbor)
        assert seen == cells

for rows, cols in ((2, 2), (2, 4), (3, 4), (4, 4)):
